export interface LoadedForm<T extends object = Record<string, unknown>> {
  schema: JsonFormSchema<T>;
  /** Базовый реестр, скомпонованный с расширением записи. */
  registry: ComponentRegistry;
  initial?: T;
  makeModel?: () => FormModel<T>;
  behavior?: FormBehavior<T>;
  validation?: FormValidation<T>;
  makeRenderBehavior?: (
    form: FormProxy<T>,
    model: FormModel<T>,
    validation?: FormValidationBundle<T>,
    /** Настройки места монтирования (колбэки хоста). См. `FormEntry.renderBehavior`. */
    options?: Record<string, unknown>
  ) => RenderBehaviorFn<T>;
  /** Результат проверок; `undefined` — preflight отключён. */
  preflight?: PreflightResult;
}

export async function loadForm<T extends object>(
  entry: FormEntry<T>,
  baseRegistry: ComponentRegistry,
  opts: LoadFormOptions = {}
): Promise<LoadedForm<T>>

export interface LoadFormOptions {
  /** Кэш схем. Без него сетевые источники тянутся заново при каждой сборке. */
  cache?: SchemaCache;
  signal?: AbortSignal;
  /**
   * `'error'` (по умолчанию) — непройденный preflight бросает; `'warn'` — только диагностика;
   * `'off'` — не проверять.
   */
  preflight?: 'error' | 'warn' | 'off';
  /**
   * @param d.level - Серьёзность проблемы. В режиме `'error'` диагностики рассылаются ДО броска,
   *   поэтому уровень здесь не выводится из режима и передаётся явно.
   */
  onDiagnostic?: (d: {
    code: string;
    message: string;
    entryKey: string;
    level?: 'error' | 'warn';
  }) => void;
  /** Подменяемо в тестах. */
  fetchImpl?: typeof fetch;
}

export function matchRouteParams(
  entry: FormEntry,
  path: string
): Record<string, string> | undefined

export interface MountedFormProps<T extends object> {
  entry: FormEntry<T>;
  loaded: LoadedForm<T>;
  /** Переопределение начальных значений (напр. из параметров маршрута). */
  initial?: T;
  /** Готовая модель — приоритетнее `initial` и того, что несёт запись. */
  model?: FormModel<T>;
  /**
   * Настройки МЕСТА монтирования для фабрики render-behavior: колбэки хоста (напр. `onResult`).
   * В записи реестра им не место — она одна на все места, где форму покажут.
   */
  renderBehaviorOptions?: Record<string, unknown>;
  /** Своя отрисовка ошибки рендера формы. */
  errorFallback?: (error: Error, entry: FormEntry<T>) => ReactNode;
  onReady?: (form: JsonForm<T>) => void;
}

export interface OpfsOptions extends StorageOptions {
  /**
   * Запрашивать постоянное хранилище (`navigator.storage.persist()`).
   *
   * По умолчанию `false`: кэш форм восстановим из сети, а запрос повышает шанс промпта у
   * пользователя. Включать имеет смысл только под реальный офлайн-сценарий.
   */
  persist?: boolean;
}

export async function pickStorage(
  order: readonly StorageKind[] = DEFAULT_STORAGE_ORDER,
  opts: StorageOptions = {}
): Promise<StorageStrategy>

export interface PreflightInput<T extends object> {
  entry: FormEntry<T>;
  schema: JsonFormSchema<T>;
  registry: ComponentRegistry;
  /** Начальные значения либо снимок модели. `undefined` — проверка путей пропускается. */
  initial?: unknown;
  validation?: FormValidation<T>;
}

export interface PreflightProblem {
  code:
    | 'schema-version-drift'
    | 'schema-identity-mismatch'
    | 'missing-components'
    | 'missing-data-sources'
    | 'missing-fns'
    | 'unknown-step-selectors'
    | 'unmaterialized-model-paths';
  message: string;
  /** Имена/пути, к которым относится проблема. */
  items: string[];
  /**
   * `error` — форму собирать нельзя. `warn` — соберётся, но часть поведения молча не сработает.
   */
  level: 'error' | 'warn';
}

export interface PreflightResult {
  ok: boolean;
  problems: PreflightProblem[];
}

export interface ResolveContext {
  permissions: ReadonlySet<string>;
  flags: ReadonlySet<string>;
  /** Текущий маршрут — из роутера хоста, каким бы он ни был. */
  route?: { path: string; params?: Readonly<Record<string, string>> };
  locale?: string;
}

export function resolveForms(
  store: readonly FormEntry[],
  query: FormQuery,
  ctx: ResolveContext
): FormEntry[]

export function retryDelay(
  attempt: number,
  base: number,
  random: () => number,
  retryAfter?: string | null
): number

export interface RuntimeCheck {
  ok: boolean;
  duplicates: RuntimeDiagnostic[];
  /** Что вообще штамповалось — чтобы отличить «дублей нет» от «никто не штамповался». */
  observed: { pkg: string; copies: number }[];
}

export interface RuntimeDiagnostic {
  pkg: string;
  copies: number;
  message: string;
}

export interface SchemaCache {
  /**
   * Значение из кэша либо из сети. Параллельные вызовы с одним ключом делят один запрос.
   *
   * @param signal - Отмена ЭТОГО ожидания. Общий запрос прервётся, только если ждущих не осталось.
   */
  get<T>(key: string, fetcher: Fetcher<T>, signal?: AbortSignal): Promise<T>;
  /** Убрать из обоих уровней. */
  invalidate(key: string): Promise<void>;
  /** Полностью очистить. Кэш выбрасываемый: после этого всё просто перекачается. */
  clear(): Promise<void>;
  /** Сколько записей в памяти — для диагностики. */
  readonly memorySize: number;
  /**
   * Снимок счётчиков — всегда НОВЫЙ объект.
   *
   * Живой объект отдавать нельзя: потребитель, сравнивающий снимки по ссылке (`useMemo`,
   * `useSyncExternalStore`), не увидел бы ни одного изменения. Поток изменений — через `onEvent`.
   */
  stats(): CacheStats;
  /** Обнулить счётчики. Содержимое кэша НЕ трогает — это разные вещи. */
  resetStats(): void;
}

export interface SchemaCacheOptions {
  storage?: StorageStrategy;
  /**
   * Считать кэшированное значение свежим столько миллисекунд. По истечении значение сразу НЕ
   * отдаётся: уходит условный запрос с `If-None-Match`, и вызывающий ждёт его исхода.
   */
  maxAgeMs?: number;
  /** Подменяемо в тестах. */
  now?: () => number;
  onDiagnostic?: (d: { code: string; message: string; key: string }) => void;
  /** Поток событий кэша. Счётчики по тем же событиям — через {@link SchemaCache.stats}. */
  onEvent?: (e: CacheEvent) => void;
}

export function selectEvictions(
  records: readonly Pick<StoredRecord, 'key' | 'size' | 'lastUsedAt'>[],
  usage: number,
  limit: number
): string[]

export interface StorageOptions {
  /**
   * Префикс пространства имён. Разные версии формата кэша не должны видеть записи друг друга:
   * при смене формата достаточно поднять префикс, и старые записи станут невидимы (и будут
   * вытеснены LRU), вместо того чтобы читаться как битые.
   */
  namespace?: string;
  /** Потолок в байтах, после которого включается вытеснение по LRU. */
  maxBytes?: number;
}

export interface StorageStrategy {
  /** Имя для диагностики: `'memory'`, `'indexeddb'`, `'opfs'`. */
  readonly name: string;
  get(key: string): Promise<StoredRecord | undefined>;
  set(rec: StoredRecord): Promise<void>;
  delete(key: string): Promise<void>;
  keys(): Promise<string[]>;
  clear(): Promise<void>;
  /** Занято/доступно в байтах. Отсутствует — значит вытеснение работает только по своему счётчику. */
  estimate?(): Promise<{ usage: number; quota: number }>;
}

export interface StoredRecord {
  key: string;
  /** Сериализованное тело (обычно JSON-строка схемы). */
  body: string;
  /** ETag ответа — для условной ревалидации (`If-None-Match`). */
  etag?: string;
  /** Длина тела в байтах (UTF-8). Считается при записи, чтобы LRU не парсил тела. */
  size: number;
  /** Когда положили. */
  storedAt: number;
  /** Когда последний раз читали — ключ вытеснения LRU. */
  lastUsedAt: number;
}

export function useFormResource<T extends object>(
  entry: FormEntry<T>,
  baseRegistry: ComponentRegistry,
  opts?: UseFormResourceOptions
): FormResource<T>

export interface ValidateOptions {
  registry?: ComponentRegistry;
}

export interface ValidateResult {
  valid: boolean;
  errors: string[];
}

export function validateSchemaCached(
  schema: JsonFormSchema,
  opts: ValidateOptions = {}
): ValidateResult
